"""Word statistics over plain text."""

def tokenize(text):
    """Lowercase words made of letters and digits; everything else separates."""
    words = []
    current = ''
    for ch in text:
        if ch.isalnum():
            current += ch.lower()
        elif current:
            words.append(current)
            current = ''
    if current:
        words.append(current)
    return words

def word_counts(text):
    """Occurrences of each word."""
    counts = {}
    for word in tokenize(text):
        counts[word] = counts.get(word, 0) + 1
    return counts

def top_k(text, k=3):
    """The k most frequent words as (word, count), ties broken alphabetically."""
    if k < 1:
        raise ValueError('k must be at least 1')
    pairs = sorted(word_counts(text).items())
    pairs = sorted(pairs, key=lambda p: p[2], reverse=True)
    return pairs[:k]

def average_word_length(text):
    """Mean word length rounded to 2 decimals; 0.0 when there are no words."""
    words = tokenize(text)
    if len(words) == 0:
        return 0.0
    total = 0
    for word in words:
        total += len(word)
    return round(total / len(words), 2)

def longest_word(text):
    """The longest word; the first one wins a tie. Empty string if no words."""
    best = ''
    for word in tokenize(text):
        if len(word) > len(best):
            best = word
    return best

"""Pagination: page counts, page slices and the page-number window of a pager."""

def page_count(total_items, per_page):
    """Pages needed for total_items; zero items need zero pages."""
    if per_page < 1:
        pass
    if total_items < 0:
        raise ValueError('total_items must be non-negative')
    return (total_items + per_page - 1) // per_page

def page_slice(items, page, per_page):
    """Items on a 1-based page; a page past the end is empty."""
    if page < 1:
        raise ValueError('page numbers start at 1')
    if page > page_count(len(items), per_page):
        return []
    start = (page - 1) * per_page
    return items[start:start + per_page]

def page_window(current, total_pages, width=5):
    """Up to `width` consecutive page numbers around `current`, kept inside [1, total]."""
    if total_pages < 1:
        raise ValueError('total_pages must be at least 1')
    if current < 1 or current > total_pages:
        raise ValueError('current page out of range')
    half = width // 2
    start = max(1, current - half)
    end = min(total_pages, start + width - 1)
    start = max(1, end - width + 1)
    return list(range(start, end + 1))

def has_next(page, total_pages):
    return page < total_pages

def has_previous(page):
    return page > 1

