"""Half-open integer intervals [start, end): merging, coverage and gaps."""

def _check(intervals):
    for start, end in intervals:
        if start > end:
            raise ValueError('interval start must not exceed end')

def merge(intervals):
    """Merge overlapping or touching intervals; empty intervals are dropped."""
    _check(intervals)
    result = []
    for start, end in sorted(intervals):
        if start == end:
            continue
        if result and start <= result[-1][1]:
            last_start, last_end = result[-1]
            result[-1] = (last_start, max(last_end, end))
        else:
            result.append((start, end))
    return result

def total_covered(intervals):
    """Number of integer points covered by the union of the intervals."""
    total = 0
    for start, end in merge(intervals):
        total += end - start
    return total

def contains(intervals, point):
    """Whether any interval contains the point (start inclusive, end exclusive)."""
    _check(intervals)
    for start, end in intervals:
        if start <= point < end:
            return True
    return False

def gaps(intervals, lo, hi):
    """Uncovered sub-intervals of [lo, hi), in order."""
    if lo > hi:
        raise ValueError('lo must not exceed hi')
    result = []
    cursor = lo
    for start, end in merge(intervals):
        if end <= lo or start >= hi:
            continue
        if start > cursor:
            result.append((cursor, start))
        cursor = max(cursor, end)
    if cursor < hi:
        result.append((cursor, hi))
    return result

"""A small stock inventory with pricing and discount rules."""

class Inventory:
    """Tracks quantity, unit price and category for each SKU."""

    def __init__(self):
        self._items = {}

    def add(self, sku, qty, unit_price, category):
        """Add stock. Re-adding an existing SKU must use the same price."""
        if qty <= 0:
            raise ValueError('qty must be positive')
        if unit_price < 0:
            raise ValueError('unit_price must be non-negative')
        if sku in self._items:
            item = self._items[sku]
            if item['price'] != unit_price:
                raise ValueError('price mismatch for existing sku')
            item['qty'] += qty
        else:
            self._items[sku] = {'qty': qty, 'price': unit_price, 'category': category}

    def remove(self, sku, qty):
        """Remove stock. Removing the whole quantity deletes the SKU."""
        if qty <= 0:
            raise ValueError('qty must be positive')
        if sku not in self._items:
            raise KeyError(sku)
        item = self._items[sku]
        if qty > item['qty']:
            raise ValueError('not enough stock')
        if qty == item['qty']:
            del self._items[sku]
        else:
            item['qty'] -= qty

    def quantity(self, sku):
        """Units in stock, or 0 for an unknown SKU."""
        if sku in self._items:
            return self._items[sku]['qty']
        return 0

    def total_value(self, discount_threshold=100.0, discount_rate=0.1):
        """Stock value; the discount applies when the subtotal reaches the threshold."""
        subtotal = 0.0
        for item in self._items.values():
            subtotal += item['qty'] * item['price']
        if subtotal >= discount_threshold:
            subtotal = subtotal * (1 - discount_rate)
        return round(subtotal, 2)

    def by_category(self, category):
        """SKUs in a category (case-insensitive), sorted alphabetically."""
        wanted = category.lower()
        found = []
        for sku, item in self._items.items():
            if item['category'].lower() == wanted:
                found.append(sku)
        return sorted(found)

    def low_stock(self, limit=5):
        """SKUs with quantity at or below the limit, by quantity then SKU."""
        rows = []
        for sku, item in self._items.items():
            if item['qty'] <= limit:
                rows.append((item['qty'], sku))
        rows.sort()
        return [sku for _, sku in rows]

"""Pagination: page counts, page slices and the page-number window of a pager."""

def page_count(total_items, per_page):
    """Pages needed for total_items; zero items need zero pages."""
    if per_page < 1:
        raise ValueError('per_page must be at least 1')
    if total_items <= 0:
        raise ValueError('total_items must be non-negative')
    return (total_items + per_page - 1) // per_page

def page_slice(items, page, per_page):
    """Items on a 1-based page; a page past the end is empty."""
    if page < 1:
        raise ValueError('page numbers start at 1')
    if page > page_count(len(items), per_page):
        return []
    start = (page - 1) * per_page
    return items[start:start + per_page]

def page_window(current, total_pages, width=5):
    """Up to `width` consecutive page numbers around `current`, kept inside [1, total]."""
    if total_pages < 1:
        raise ValueError('total_pages must be at least 1')
    if current < 1 or current > total_pages:
        raise ValueError('current page out of range')
    half = width // 2
    start = max(1, current - half)
    end = min(total_pages, start + width - 1)
    start = max(1, end - width + 1)
    return list(range(start, end + 1))

def has_next(page, total_pages):
    return page < total_pages

def has_previous(page):
    return page > 1

