    pairs = sorted(word_counts(text).items())
    pairs = sorted(pairs, key=lambda p: p[1], reverse=True)
    return pairs[:k]

def average_word_length(text):
    """Mean word length rounded to 2 decimals; 0.0 when there are no words."""
    words = tokenize(text)
    if len(words) == 0:
        return 0.0
    total = 0
    for word in words:
        total += len(word)
    return round(total / len(words), 2)

def longest_word(text):
    """The longest word; the first one wins a tie. Empty string if no words."""
    best = ''
    for word in tokenize(text):
        if len(word) > len(best):
            best = word
    return best

"""Grading helpers: letter grades, weighted averages, curving and ranking."""

def letter(score):
    """Letter grade for a score in [0, 100]: A >= 90, B >= 80, C >= 70, D >= 60."""
    if score < 0 or score > 100:
        raise ValueError('score must be between 0 and 100')
    if score > 90:
        return 'A'
    if score >= 80:
        return 'B'
    if score >= 70:
        return 'C'
    if score >= 60:
        return 'D'
    return 'F'

def weighted_average(scores, weights):
    """Weighted mean rounded to 2 decimals."""
    if len(scores) != len(weights) or len(scores) == 0:
        raise ValueError('scores and weights must be non-empty and the same length')
    total_weight = 0
    total = 0
    for s, w in zip(scores, weights):
        if w < 0:
            raise ValueError('weights must be non-negative')
        total += s * w
        total_weight += w
    if total_weight == 0:
        raise ValueError('weights must not all be zero')
    return round(total / total_weight, 2)

def curve(scores, target_max=100):
    """Shift every score so the best becomes target_max, clamped to [0, 100]."""
    if not scores:
        return []
    shift = target_max - max(scores)
    result = []
    for s in scores:
        result.append(min(100, max(0, s + shift)))
    return result

def rank(scores):
    """Competition ranking: highest is 1, ties share a rank, the next rank skips."""
    ranks = []
    for s in scores:
        higher = 0
        for other in scores:
            if other > s:
                higher += 1
        ranks.append(higher + 1)
    return ranks

def passed_count(scores, cutoff=60):
    """How many scores are at or above the cutoff."""
    count = 0
    for s in scores:
        if s >= cutoff:
            count += 1
    return count

"""Half-open integer intervals [start, end): merging, coverage and gaps."""

def _check(intervals):
    for start, end in intervals:
        if start > end:
            raise ValueError('interval start must not exceed end')

def merge(intervals):
    """Merge overlapping or touching intervals; empty intervals are dropped."""
    _check(intervals)
    result = []
    for start, end in sorted(intervals):
        if start == end:
            continue
        if result and start <= result[-1][1]:
            last_start, last_end = result[-1]
            result[-1] = (last_start, max(last_end, end))
        else:
            result.append((start, end))
    return result

def total_covered(intervals):
    """Number of integer points covered by the union of the intervals."""
    total = 0
    for start, end in merge(intervals):
        total += end - start
    return total

def contains(intervals, point):
    """Whether any interval contains the point (start inclusive, end exclusive)."""
    _check(intervals)
    for start, end in intervals:
        if start <= point < end:
            return True
    return False

def gaps(intervals, lo, hi):
    """Uncovered sub-intervals of [lo, hi), in order."""
    if lo > hi:
        raise ValueError('lo must not exceed hi')
    result = []
    cursor = lo
    for start, end in merge(intervals):
        if end <= lo or start >= hi:
            continue
        if start > cursor:
            result.append((cursor, start))
        cursor = max(cursor, end)
    if cursor < hi:
        result.append((cursor, hi))
    return result

"""A small stock inventory with pricing and discount rules."""

class Inventory:
    """Tracks quantity, unit price and category for each SKU."""

    def __init__(self):
        self._items = {}

    def add(self, sku, qty, unit_price, category):
        """Add stock. Re-adding an existing SKU must use the same price."""
        if qty <= 0:
            raise ValueError('qty must be positive')
        if unit_price < 0:
            raise ValueError('unit_price must be non-negative')
        if sku in self._items:
            item = self._items[sku]
            if item['price'] != unit_price:
                raise ValueError('price mismatch for existing sku')
            item['qty'] += qty
        else:
            self._items[sku] = {'qty': qty, 'price': unit_price, 'category': category}

    def remove(self, sku, qty):
        """Remove stock. Removing the whole quantity deletes the SKU."""
        if qty <= 0:
            raise ValueError('qty must be positive')
        if sku not in self._items:
            raise KeyError(sku)
        item = self._items[sku]
        if qty > item['qty']:
            raise ValueError('not enough stock')
        if qty == item['qty']:
            del self._items[sku]
        else:
            item['qty'] -= qty

    def quantity(self, sku):
        """Units in stock, or 0 for an unknown SKU."""
        if sku in self._items:
            return self._items[sku]['qty']
        return 0

    def total_value(self, discount_threshold=100.0, discount_rate=0.1):
        """Stock value; the discount applies when the subtotal reaches the threshold."""
        subtotal = 0.0
        for item in self._items.values():
            subtotal += item['qty'] * item['price']
        if subtotal >= discount_threshold:
            subtotal = subtotal * (1 - discount_rate)
        return round(subtotal, 2)

    def by_category(self, category):
        """SKUs in a category (case-insensitive), sorted alphabetically."""
        wanted = category.lower()
        found = []
        for sku, item in self._items.items():
            if item['category'].lower() == wanted:
                found.append(sku)
        return sorted(found)

    def low_stock(self, limit=5):
        """SKUs with quantity at or below the limit, by quantity then SKU."""
        rows = []
        for sku, item in self._items.items():
            if item['qty'] <= limit:
                rows.append((item['qty'], sku))
        rows.sort()
        return [sku for _, sku in rows]

